    skos:narrower she:SSVAgriculture .

she:SSVAgriculture a skos:Concept ;
    skos:prefLabel "ssv agriculture" ;
    she:isAssessedBy she:LevelInSoilGreaterThanSSVAgriculture,
                     she:LevelInSoilLessThanSSVAgriculture .

she:Assessment a skos:Concept ;
    skos:prefLabel "assessment" .

she:LevelInSoilGreaterThanSSVAgriculture a skos:Concept ;
    skos:prefLabel "level in soil > ssv agriculture" ;
    she:leadsToAssessment she:NotSuitableActionsRequired .

she:LevelInSoilLessThanSSVAgriculture a skos:Concept ;
    skos:prefLabel "level in soil < ssv agriculture" ;
    she:leadsToAssessment she:SuitableLandUsePosesNoRisk .

she:AssessmentSoilQuality a skos:Concept ;
    skos:prefLabel "assessment soil quality" .

she:NotSuitableActionsRequired a skos:Concept ;
    skos:prefLabel "not suitable, actions required" .

she:SuitableLandUsePosesNoRisk a skos:Concept ;
    skos:prefLabel "suitable, land use poses no risk" .

triples_A_turtle:
@prefix she: <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:EcosystemService a skos:Concept ;
    skos:prefLabel "ecosystem service" ;
    she:leadsTo she:SoilFunction .

she:SoilFunction a skos:Concept ;
    skos:prefLabel "soil function" ;
    she:leadsTo she:Endpoints .

she:Endpoints a skos:Concept ;
    skos:prefLabel "endpoints" ;
    she:informsAssessmentOf she:SoilWaterProductQuality .

she:ChangeOfLandUseAndOrManagement a skos:Concept ;
    skos:prefLabel "change of land use and/or management" ;
    she:affects she:SoilWaterProductQuality .

she:SoilWaterProductQuality a skos:Concept ;
    skos:prefLabel "soil/ water/ product/ quality" ;
    she:comparedAgainst she:ThresholdsLimits .

she:ThresholdsLimits a skos:Concept ;
    skos:prefLabel "thresholds (limits)" ;
    she:informs she:Evaluation .

she:Evaluation a skos:Concept ;
    skos:prefLabel "evaluation" ;
    she:resultsIn she:ActualLevelLessThanThreshold,
        she:ActualLevelGreaterThanThreshold .

she:ActualLevelLessThanThreshold a skos:Concept ;
    skos:prefLabel "actual level < threshold" .

she:ActualLevelGreaterThanThreshold a skos:Concept ;
    skos:prefLabel "actual level > threshold" ;
    she:triggers she:ActionNeededPolicyInduced .

she:ActionNeededPolicyInduced a skos:Concept ;
    skos:prefLabel "action needed (policy induced)" ;
    she:induces she:ChangeOfLandUseAndOrManagement .

triples_B_turtle:
@prefix she:  <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:EcosystemService a skos:Concept ;
