    she:isAssessedAs she:SoilWaterProductQuality .

she:ChangeOfLandUseAndOrManagement a skos:Concept ;
    skos:prefLabel "change of land use and/or management" ;
    she:affects she:SoilWaterProductQuality .

she:SoilWaterProductQuality a skos:Concept ;
    skos:prefLabel "soil/ water/ product/ quality" ;
    she:isComparedTo she:ThresholdsLimits .

she:ThresholdsLimits a skos:Concept ;
    skos:prefLabel "thresholds (limits)" ;
    she:informs she:Evaluation .

she:Evaluation a skos:Concept ;
    skos:prefLabel "evaluation" ;
    she:hasOutcome she:ActualLevelLessThanThreshold,
                   she:ActualLevelGreaterThanThreshold .

she:ActualLevelLessThanThreshold a skos:Concept ;
    skos:prefLabel "actual level < threshold" .

she:ActualLevelGreaterThanThreshold a skos:Concept ;
    skos:prefLabel "actual level > threshold" ;
    she:triggers she:ActionNeededPolicyInduced .

she:ActionNeededPolicyInduced a skos:Concept ;
    skos:prefLabel "action needed (policy induced)" ;
    she:influences she:ChangeOfLandUseAndOrManagement .

triples_A_turtle:
@prefix she:  <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:DynamicAssessmentOfSoilHealth a skos:Concept ;
    skos:prefLabel "dynamic assessment of soil health" ;
    skos:narrower she:Unhealthy,
                  she:Intermediate,
                  she:Healthy .

she:Unhealthy a skos:Concept ;
    skos:prefLabel "unhealthy" ;
    skos:definition "at least one indicator exceeds thresholds for unacceptable degradation (ecosystem services significantly compromised)" ;
    she:isDeterminedBy she:ThresholdForUnacceptableDegradation ;
    she:hasCondition she:IndicatorExceedsUnacceptableDegradationThreshold .

she:Intermediate a skos:Concept ;
    skos:prefLabel "intermediate" ;
    skos:definition "slight soil degradation at warning level (pre-cautionary soil protection)" ;
    she:hasCriterion she:ExceedanceOfThresholdsForIntermediateRisk,
                    she:PositiveIndicatorTrendWhileUnacceptableDegradationThresholdsExceeded,
                    she:NegativeIndicatorTrendWithoutAnyThresholdExceedance,
                    she:SustainableSoilManagementInPlaceWhileThresholdsExceeded .

she:Healthy a skos:Concept ;
    skos:prefLabel "healthy" ;
    skos:definition "none of the indicators shows any threshold exceedance" ;
    she:isDeterminedBy she:ThresholdForUnacceptableDegradation ;
    she:hasCondition she:NoThresholdExceedance .

she:ThresholdForUnacceptableDegradation a skos:Concept ;
    skos:prefLabel "threshold for unacceptable degradation" .

she:IndicatorsFromMonitoring a skos:Concept ;
    skos:prefLabel "indicators from monitoring" ;
    she:isMeasuredOver she:Time ;
    she:canShowTrend she:PositiveTrend,
                    she:NegativeTrend .

she:Time a skos:Concept ;
    skos:prefLabel "time" .

she:PositiveTrend a skos:Concept ;
    skos:prefLabel "positive trend" .

she:NegativeTrend a skos:Concept ;
    skos:prefLabel "negative trend" .

she:IndicatorExceedsUnacceptableDegradationThreshold a skos:Concept ;
    skos:prefLabel "indicator exceeds unacceptable degradation threshold" ;
    she:refersTo she:ThresholdForUnacceptableDegradation .

she:NoThresholdExceedance a skos:Concept ;
    skos:prefLabel "no threshold exceedance" ;
    she:refersTo she:ThresholdForUnacceptableDegradation .

she:ExceedanceOfThresholdsForIntermediateRisk a skos:Concept ;
    skos:prefLabel "exceedance of thresholds for intermediate risk (where available)" .

she:PositiveIndicatorTrendWhileUnacceptableDegradationThresholdsExceeded a skos:Concept ;
    skos:prefLabel "positive indicator trend while thresholds for unacceptable degradation are still exceeded" ;
    she:involves she:PositiveTrend,
                she:ThresholdForUnacceptableDegradation .

she:NegativeIndicatorTrendWithoutAnyThresholdExceedance a skos:Concept ;
    skos:prefLabel "negative indicator trend without any threshold exceedance" ;
    she:involves she:NegativeTrend .

she:SustainableSoilManagementInPlaceWhileThresholdsExceeded a skos:Concept ;
    skos:prefLabel "sustainable soil management in place while thresholds are exceeded" ;
    she:involves she:ThresholdForUnacceptableDegradation .

