    she:hasSource "Schjønning (2021), Schjønning et al. (2020)" .

she:PedotransferFunctionsWaterRetentionAndResistance a skos:Concept ;
    skos:prefLabel "pedotransfer functions of water retention curves and soil resistance to penetration" ;
    she:hasSource "Imhoff et al. (2015)" .

